input.proposed_solution:
Map the sort key through a fixed allowlist of column identifiers (own-property check, so prototype keys fall back) and reduce dir to ASC/DESC, then interpolate only those constants into ORDER BY. Added tests with injection attempts.

Patch (already applied in the repository snapshot):
```diff
--- a/src/queries.js
+++ b/src/queries.js
@@ -1,9 +1,18 @@
 // @ts-check

+/** Sortable columns. Keys are what the API accepts; values are fixed SQL identifiers. */
+const SORT_COLUMNS = /** @type {const} */ ({ created: "created_at", total: "total", id: "id" });
+
 /**
- * @param {{ status: string }} filter
+ * Identifiers cannot be bound as $n parameters in PostgreSQL, so the ORDER BY column and direction
+ * are interpolated - but only from the fixed SORT_COLUMNS map and a two-value direction switch.
+ * Unknown keys fall back to the default; user text never reaches the SQL string.
+ * @param {{ status: string, sort?: string, dir?: string }} filter
  * @returns {{ text: string, values: unknown[] }}
  */
 export function listInvoicesQuery(filter) {
-  return { text: "SELECT id, total, created_at FROM invoices WHERE status = $1 ORDER BY created_at DESC", values: [filter.status] };
+  const key = /** @type {keyof typeof SORT_COLUMNS} */ (filter.sort ?? "created");
+  const column = Object.hasOwn(SORT_COLUMNS, key) ? SORT_COLUMNS[key] : SORT_COLUMNS.created;
+  const dir = filter.dir === "asc" ? "ASC" : "DESC";
+  return { text: `SELECT id, total, created_at FROM invoices WHERE status = $1 ORDER BY ${column} ${dir}`, values: [filter.status] };
 }
--- a/test/queries.test.js
+++ b/test/queries.test.js
@@ -7,3 +7,15 @@
   assert.deepEqual(q.values, ["paid"]);
   assert.match(q.text, /ORDER BY created_at DESC$/);
 });
+
+test("sort by allowlisted column", () => {
+  assert.match(listInvoicesQuery({ status: "paid", sort: "total", dir: "asc" }).text, /ORDER BY total ASC$/);
+});
+
+test("injection attempts fall back to the default", () => {
+  const q = listInvoicesQuery({ status: "x", sort: "created_at; DROP TABLE invoices", dir: "desc; --" });
+  assert.match(q.text, /ORDER BY created_at DESC$/);
+  assert.doesNotMatch(q.text, /DROP/);
+  assert.match(listInvoicesQuery({ status: "x", sort: "__proto__" }).text, /ORDER BY created_at DESC$/);
+  assert.match(listInvoicesQuery({ status: "x", sort: "toString" }).text, /ORDER BY created_at DESC$/);
+});
```
